/**
 * Inline SVG icon. Unknown names return an empty string (never an error).
 * The icon is decorative (aria-hidden); put a text label or aria-label on the
 * surrounding button/link.
 */
function icon(string $name, string $class = ''): string
{
    $icons = heroiconPaths();

    if (!isset($icons[$name])) {
        return '';
    }

    $classes = 'icon icon-' . $name . ($class !== '' ? ' ' . $class : '');

    return '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" ' .
        'stroke-width="1.5" stroke="currentColor" aria-hidden="true" focusable="false" ' .
        'class="' . htmlspecialchars($classes, ENT_QUOTES, 'UTF-8') . '">' .
        $icons[$name] . '</svg>';
}

/**
 * Several icons at once (used to hand the editor toolbar icons to JavaScript).
 *
 * @param  string[] $names
 * @return array<string, string>
 */
function iconSet(array $names): array
{
    $set = [];

    foreach ($names as $name) {
        $svg = icon($name);

        if ($svg !== '') {
            $set[$name] = $svg;
        }
    }

    return $set;
}

/**
 * Favicon (data: URI, so no extra request): the Heroicons "link" icon in
 * white on the brand colour.
 */
function faviconHref(): string
{
    $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">' .
        '<rect width="64" height="64" rx="14" fill="#315efb"/>' .
        '<g transform="translate(12 12) scale(1.6667)" fill="none" stroke="#ffffff" stroke-width="1.5">' .
        (heroiconPaths()['link'] ?? '') .
        '</g></svg>';

    return 'data:image/svg+xml,' . rawurlencode($svg);
}

/**
 * Alert box with a status icon. Type: success | error | warning | info.
 * The message is always escaped. Errors use role="alert" so screen readers
 * announce them immediately.
 */
function alertHtml(string $type, string $message): string
{
    $icons = [
        'success' => 'check-circle',
        'error' => 'exclamation-circle',
        'warning' => 'exclamation-triangle',
        'info' => 'information-circle',
    ];

    if (!isset($icons[$type])) {
        $type = 'info';
    }

    return '<div class="alert alert-' . $type . '" role="' . ($type === 'error' ? 'alert' : 'status') . '">' .
        icon($icons[$type]) .
        '<span>' . htmlspecialchars($message, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</span></div>';
}
